  FT["PH-H3166"] = {"id":"PH-H3166","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3863_1964.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Naujan市","en":"An Act Declaring the Natural Hot Springs at Montelago, Municipality of Naujan, Province of Oriental Mindoro, a Tourist Resort","orig":"An Act Declaring the Natural Hot Springs at Montelago, Municipality of Naujan, Province of Oriental Mindoro, a Tourist Resort"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3863","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-12","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3863_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3166-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The natural hot springs at Montelago, Municipality of Naujan, Province of Oriental Mindoro, is hereby declared a tourist resort."}},{"id":"PH-H3166-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of six hundred thousand pesos is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, for the construction of buildings, roads and other facilities including the construction of a wharf during the fiscal year nineteen hundred sixty-five. Thereafter, such sums as may be needed for its operation, maintenance and improvement shall be included in the annual General Appropriations Act."}},{"id":"PH-H3166-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 12, 1964."}}],"pack":"ph-p45"};
  FT["PH-H3167"] = {"id":"PH-H3167","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3864_1964.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"增加萨马省Allen市镇急诊医院床位并授权为此追加拨款的法案","en":"An Act Increasing the Bed Capacity of Allen Emergency Hospital in the Municipality of Allen, Province of Samar, and Authorizing the Additional Appropriation of Funds Therefor","orig":"An Act Increasing the Bed Capacity of Allen Emergency Hospital in the Municipality of Allen, Province of Samar, and Authorizing the Additional Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 3864","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-12","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3864_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3167-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of Allen Emergency Hospital in the Municipality of Allen, Province of Samar, is hereby increased from twenty-five to fifty."}},{"id":"PH-H3167-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Additional sum necessary in accordance with the provisions of Republic Act Numbered Nineteen hundred thirty-nine is hereby authorized to be appropriated to carry out the purposes of this Act for the fiscal year nineteen hundred and sixty-five, in addition to its existing appropriations. Thereafter, said sums shall be included in the annual General Appropriations Act."}},{"id":"PH-H3167-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 12, 1964."}}],"pack":"ph-p45","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of Allen Emergency Hospital in the Municipality of Allen, Province of Samar, and Authorizing the Additional Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3168"] = {"id":"PH-H3168","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3865_1964.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第409号共和国法第XIV-A条（即马尼拉市 Revised Charter）的法案","en":"An Act Amending Article XIV-A of Republic Act Numbered Four Hundred and Nine, Otherwise Known as the Revised Charter of the City of Manila","orig":"An Act Amending Article XIV-A of Republic Act Numbered Four Hundred and Nine, Otherwise Known as the Revised Charter of the City of Manila"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3865","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-12","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3865_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3168-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Article XIV-A of Republic Act Numbered Four hundred and nine, otherwise known as the Revised Charter of the City of Manila, as inserted by Republic Act Numbered One thousand eight hundred and forty-two, is further amended to read as follows:\n\" Article XIV -A Veterinary Inspection Board \"Sec. 80-A. Composition. -There is hereby created a Veterinary Inspection Board which shall be composed of the Chairman and three members: Provided, That nothing in this law shall affect the tenures of office of the incumbent Chairman and two members of the Meat Inspection Board who shall automatically serve in the same position and capacity in the Veterinary Inspection Board upon approval of this Act: And Provided, further, That the third member shall be incumbent technical assistant on veterinary matters of the Meat Inspection Board. The Chairman shall receive a compensation of fourteen thousand pesos per annum and each of the three members shall receive twelve thousand pesos per annum.\""}},{"id":"PH-H3168-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 12, 1964."}}],"pack":"ph-p45","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Article XIV-A of Republic Act Numbered Four Hundred and Nine, Otherwise Known as the Revised Charter of the City of Manila","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3169"] = {"id":"PH-H3169","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3866_1964.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"设立Danao市","en":"An Act Establishing a Ceramic Processing Plant in the City of Danao, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a Ceramic Processing Plant in the City of Danao, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3866","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-12","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3866_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3169-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established a ceramic processing plant in a place to be chosen by the Commissioner of the National Institute of Science and Technology in the City of Danao, where sufficient quantities of ceramic materials are found."}},{"id":"PH-H3169-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The ceramic processing plant shall have the following functions:\n(a) Study the efficient utilization of ceramic raw materials of the locality;\n(b) Process and compound whatever clay or other ceramic raw materials may be found in the locality for sale to potters at costs;\n(c) Mix ceramic materials for glaze to be sold at cost to potters;\n(d) Construct a community kiln for use of local potters at nominal cost;\n(e) Teach, guide and demonstrate to local potters the making of different kind of ceramic products such as structural hollow clay blocks, building bricks, tiles, and household potter wares like flower vases, art wares, containers, dinnerwares, drinking vessels, insulators, etc.; and\n(f) Conduct such researches or studies as may be necessary for the efficient and effective functioning of the plant."}},{"id":"PH-H3169-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The ceramic processing plant shall have a chief who shall be known as the Chief Ceramic Technologist and such other personnel as may be necessary. They shall be appointed by the Chairman of the National Science Development Board, upon recommendation of the Commissioner of the National Institute of Science and Technology and subject to the approval of the said board.\nThe Chief Ceramic Technician shall be responsible for the effective operation of the ceramic processing plant. He shall be under the operational direction and supervision of the Commissioner of the National Institute of Science and Technology."}},{"id":"PH-H3169-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Persons desiring to be trained in ceramics at the Ceramics Unit of the Industrial Research Center, National Institute of Science and Technology, shall apply to the head of the Ceramic Processing Plant and, upon approval of their application by the Commissioner of the National Institute of Science and Technology, shall be given a daily allowance not exceeding five pesos for a period not exceeding three months and transportation expenses from and to their province. The number of trainees and their qualifications shall be determined by the Commissioner of said Institute."}},{"id":"PH-H3169-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The proceeds from the sale of products and/or materials as well as the fees collected for services rendered by the ceramic processing plant and the unexpended balance of its annual appropriation shall be used as a revolving fund for the operation of the plant, improvement of its products, and other studies connected with the project."}},{"id":"PH-H3169-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Should the plant be sold to a private individual or corporation, the proceeds shall be employed for the establishment of similar plant or plants in other regions to be determined by the Commissioner of the National Institute of Science and Technology with the approval of the Chairman of the National Science Development Board."}},{"id":"PH-H3169-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"To carry out the purpose of this Act including the purchase of land, equipment, materials, supplies and the construction of buildings and shops in connection with the work, there is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, the sum of two hundred fifty thousand pesos for the fiscal year nineteen hundred sixty-five: Provided, That of this sum, the amount of one hundred thousand pesos shall be used for the purchase of the site. Such amount as may be necessary for the operating expenses of the plant in succeeding fiscal years shall be included in the annual General Appropriations Act."}},{"id":"PH-H3169-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 12, 1964."}}],"pack":"ph-p45"};
  FT["PH-H3170"] = {"id":"PH-H3170","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3867_1964.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"授权菲律宾慈善彩票办公室每年举办彩票或抽奖，以扩建菲律宾国家红十字会血库的法案","en":"An Act to Authorize the Philippine Charity Sweepstakes Office to Hold Annually a Lottery or Sweepstakes for the Expansion of the Philippine National Red Cross Blood Bank","orig":"An Act to Authorize the Philippine Charity Sweepstakes Office to Hold Annually a Lottery or Sweepstakes for the Expansion of the Philippine National Red Cross Blood Bank"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 3867","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-12","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3867_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3170-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Philippine Charity Sweepstakes Office is authorized to hold annually a lottery or sweepstakes, the whole proceeds of which shall, after deducting the prizes and expenses as provided for in Republic Act Numbered Eleven hundred sixty-nine, as amended, be turned over to the Philippine National Red Cross Blood Bank for its expansion and for its blood typing project."}},{"id":"PH-H3170-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 12, 1964."}}],"pack":"ph-p45","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Authorize the Philippine Charity Sweepstakes Office to Hold Annually a Lottery or Sweepstakes for the Expansion of the Philippine National Red Cross Blood Bank","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3171"] = {"id":"PH-H3171","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3868_1964.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"修订第1387号共和国法（经第1893号共和国法修正）中关于棉兰老州立大学董事会组成与权力的若干条款并为其他目的法案","en":"An Act to Amend Certain Provisions of Republic Act Numbered Thirteen Hundred and Eighty-Seven, as Amended by Republic Act Numbered Eighteen Hundred Ninety-Three, Relating to the Composition and Powers of the Board of Regents of the Mindanao State University, and for Other Purposes","orig":"An Act to Amend Certain Provisions of Republic Act Numbered Thirteen Hundred and Eighty-Seven, as Amended by Republic Act Numbered Eighteen Hundred Ninety-Three, Relating to the Composition and Powers of the Board of Regents of the Mindanao State University, and for Other Purposes"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3868","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-12","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3868_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3171-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The pertinent portions of Section four of Republic Act Numbered Thirteen hundred and eighty-seven, as amended by Republic Act Numbered Eighteen hundred and ninety-three, are hereby further amended to read as follows:\n\"The Board of regents shall be composed of ten members, five of whom shall be ex-officio members, three to be appointed by the President of the Philippines, with the consent of the Commission on Appointments, and two elected by the Mindanao State University Alumni Association: Provided, That the appointments extended to the present members of the Board shall continue until the expiration of their terms. Of the three to be appointed, the President of the Philippines shall designate one to serve for one year, one to serve for two years, and one to serve for three years.\n\"The two members shall be elected by the Mindanao State University Alumni Association from among its members as soon as there are enough graduates of said University, one to be elected for a term of one year, and the other to be elected for a term of two years: Provided, However, That in the meantime that there are not enough graduates of the said University, the President of the Republic of the Philippines shall appoint the two members with the consent of the Commission on Appointments for a term as herein above provided. Thereafter persons appointed to succeed such members shall hold office for a term of two years and until their successors are appointed or elected, as the case may be. In case of a vacancy, such vacancy shall be filled by appointment by the President of the Philippines, with the consent of the Commission on Appointments or elected by the alumni association, and such appointee or person elected shall held office for the unexpired term only. All members of the Board of Regents shall be residents of the Philippines. No persons in the employ of the University or in any other educational institution in any capacity whatsoever, whether as dean, professor, instructor, lecturer, or otherwise, shall be eligible for membership of the Board.\""}},{"id":"PH-H3171-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The fifth paragraph of the same section is hereby further amended to read as follows:\n\"The Secretary of Education, the Chairman of the Committee on Education of the Senate, the Chairman of the Committee on Education of the House of Representatives, the President of the University, and the Superintendent of Schools for the Province of Lanao del Sur shall be ex-officio members of the Board. The President of the University shall be elected and his compensation and term of office, any provision of law to the contrary notwithstanding, shall be fixed by the Board of Regents. The Secretary of Education shall be ex-officio chairman of the Board, but in his absence, the President of the University shall act in his behalf.\""}},{"id":"PH-H3171-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Paragraph (e) of Section six of Republic Act Numbered Thirteen hundred and eighty-seven on the powers and duties of the Board of Regents is hereby amended to read as follows:\n\"(e) To appoint, on the recommendation of the President of the University, professors, instructors, lecturers and other employees of the University; to fix their compensation, hours of service, and such other duties and conditions as it may deem proper; to grant to them in its discretion leave of absence under such regulations as it may promulgate, any provisions of law to the contrary notwithstanding, and to remove them for cause after an investigation and hearing shall have been had; and to extend with their consent the tenure of faculty members of the university beyond the age of sixty-five, any other provision of law to the contrary notwithstanding, on recommendation of law to the President of the University, whenever in his opinion their services are specially needed: Provided, However, That no extension of service shall be made beyond the age of seventy.\""}},{"id":"PH-H3171-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 12, 1964."}}],"pack":"ph-p45","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Provisions of Republic Act Numbered Thirteen Hundred and Eighty-Seven, as Amended by Republic Act Numbered Eighteen Hundred Ninety-Three, Relating to the Composition and Powers of the Board of Regents of the Mindanao State University, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3172"] = {"id":"PH-H3172","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3869_1964.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"增加拉乌尼翁省Agoo市镇Doña Gregoria纪念医院床位并授权为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Doña Gregoria Memorial Hospital in the Municipality of Agoo, Province of La Union, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Doña Gregoria Memorial Hospital in the Municipality of Agoo, Province of La Union, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["labor","health"],"docNumber":"Republic Act No. 3869","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-12","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3869_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3172-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Doña Gregoria Memorial Hospital in the Municipality of Agoo, Province of La Union, is hereby increased to fifty."}},{"id":"PH-H3172-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds of the National Treasury not otherwise appropriated, to carry out the purposes of this Act. Every year thereafter, the said sum must be included in the annual General Appropriations Acts."}},{"id":"PH-H3172-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 12, 1964."}}],"pack":"ph-p45","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Doña Gregoria Memorial Hospital in the Municipality of Agoo, Province of La Union, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3173"] = {"id":"PH-H3173","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3870_1964.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"界定菲律宾大学法学院中心职能、规定其经费并为其他目的法案","en":"An Act Defining the Functions of the U.P. Law Center, Providing for its Financing and for Other Purposes","orig":"An Act Defining the Functions of the U.P. Law Center, Providing for its Financing and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3870","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-12","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3870_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3173-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Continuing Legal Education and Research Center of the College of Law, University of the Philippines, also known and hereinafter referred to as the U. P. Law Center, shall perform the following functions:\n(1) To undertake technical studies and researches in law, with emphasis on Philippine Law, particularly on projects for reforms in the judiciary, public administration, civil rights protection, international relations, and law enforcement;\n(2) To undertake law institutes or study programs for continuing legal education;\n(3) To undertake legal studies and researches on request from the various agencies of the government concerned with law reform, including the committees on Revision of Laws of the House of Representatives and the Senate;\n(4) To undertake the publications of studies, monographs, research papers, articles, and other works or writings on law, with special emphasis on those related to its general objectives, and to distribute them at cost to government agencies, judges, lawyers, government administrators and other interested parties, and\n(5) To perform all other acts as may be necessary for the achievement of its objectives and functions, in accordance with the rules and regulations of the University including the granting of research awards, prizes, scholarships and fellowships."}},{"id":"PH-H3173-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Any provision of law to the contrary notwithstanding, appointments to the administrative or research staff of the U. P. Law Center may be on a part-time basis and shall be exempt from the requirements and restrictions of the Civil Service Law, the Retirement Law, and Section five hundred twenty-nine of the Revised Administrative Code: Provided , That any retiree employed in the U. P. Law Center shall not be required to reimburse or refund any gratuity received from the Government nor shall any pension or annuity to which he is entitled be suspended or reduced on account of his employment in the U. P. Law Center."}},{"id":"PH-H3173-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In order to enhance the facilities of the U. P. Law Center, no book, treatise, or other literary work on law shall be deemed entitled to copyright protection as provided in the Copyright Law, unless, in addition to the requirements therein prescribed, two copies thereof shall have been previously filed with the U. P. Law Center, as shown by official receipt thereof; and all government agencies, including the appellate courts, administrative courts, boards, and commissions, performing or discharging adjudicative, quasi-legislative functions, are hereby obliged to furnish the U. P. Law Center, free of charge and on request, with at least one copy of each decision, resolution, regulation, bulletin, or report promulgated or published by such agencies in the regular course of business. The materials thus gathered shall be open to all researchers, whether in the government service or otherwise."}},{"id":"PH-H3173-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"In order to provide for the support of the U. P. Law Center, the additional amount of five pesos in the case of the appellate courts and the additional amount of two pesos in the case of all other courts, subject to the supervision of the Department of Justice, shall be collected by their respective clerks of courts, or equivalent functionary, for each action or special proceeding filed therewith and for which the fees prescribed in the Rules of Court or for not more than one year at the discretion of the Court, in any statute or regulation are due and payable. Such additional amounts shall be receipted for separately as part of a special fund to be known as the Legal Research Fund.\""}},{"id":"PH-H3173-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Any person who willfully violates any of the provisions of this Act shall be punished with a fine of not more than two thousand pesos or with imprisonment and shall be turned over by the clerks of court to the chief accountant of the Department of Justice who in turn shall remit the same at the end of each fiscal year to the University of the Philippines for the use of the U. P. Law Center in accordance with this Act."}},{"id":"PH-H3173-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 12, 1964"}}],"pack":"ph-p45","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Defining the Functions of the U.P. Law Center, Providing for its Financing and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3174"] = {"id":"PH-H3174","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3871_1964.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订《修正行政法典》第588条的法案","en":"An Act to Amend Section Five Hundred Eighty-Eight of the Revised Administrative Code","orig":"An Act to Amend Section Five Hundred Eighty-Eight of the Revised Administrative Code"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 3871","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3871_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3174-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section five hundred eighty-eight of the Revised Administrative Code is amended to read as follows:\n\"Sec. 588. Authority of Auditor in adjustment and setting-off of accounts between offices.— The Auditor General shall have the power, subject to such regulations as he may prescribe therefore, to authorize and enforce the settlement of accounts subsisting between the different Bureaus or Offices of the National service; between any such bureau or office and any corporation owned or controlled by the government or other self-governing board, commission, or agency of the government; between corporations, self-governing boards, commission, or agencies; between any such Bureau or Office or government-owned or controlled corporation, or self-governing board, commission or agency and any provincial, municipal or city governments; and between any such provincial and municipal or city governments; the absence of appropriations therefore notwithstanding.\""}},{"id":"PH-H3174-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1964."}}],"pack":"ph-p45","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Section Five Hundred Eighty-Eight of the Revised Administrative Code","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3175"] = {"id":"PH-H3175","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3872_1964.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"公共土地法","en":"Public Land Act","orig":"An Act to Amend Sections Forty-Four, Forty-Eight and One Hundred Twenty of Commonwealth Act Numbered One Hundred Forty-One, as Amended, Otherwise Known as the \"Public Land Act\", and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3872","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-18","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3872_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3175-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"A new paragraph is hereby added to Section 44 of Commonwealth Act Numbered One hundred forty-one, to read as follows:\n\"Sec. 44. Any natural-born citizen of the Philippines who is not the owner of more than twenty-four hectares and who since July fourth, nineteen hundred and twenty-six or prior thereto, has continuously occupied and cultivated, either by himself or through his predecessors-in-interest, a tract or tracts of agricultural public lands subject to disposition, or who shall have paid the real estate tax thereon while the same has not been occupied by any person shall be entitled, under the provisions of this chapter, to have a free patent issued to him for such tract or tracts of such land not to exceed twenty-four hectares.\n\"A member of the national cultural minorities who has continuously occupied and cultivated, either by himself or through his predecessors-in-interest, a tract or tracts of land, whether disposable or not since July 4, 1955, shall be entitled to the right granted in the preceding paragraph of this section: Provided , That at the time he files his free patent application he is not the owner of any real estate secured or disposable under this provision of the Public Land Law.\""}},{"id":"PH-H3175-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"A new sub-section (c) is hereby added to Section 48 of the same Act to read as follows:\n\"Sec. 48. The following-described citizens of the Philippines, occupying lands of the public domain or claiming to own any such lands or an interest therein, but whose titles have not been perfected or completed, may apply to the Court of First Instance of the province where the land is located for confirmation of their claims and the issuance of a certificate of title therefor, under the Land Registration Act, to wit:\n\"(a) Those who prior to the transfer of sovereignty from Spain to the United States have applied for the purchase, composition or other form of grant of lands if the public domain under the laws and royal decrees then in force and have instituted and prosecuted the proceedings in connection therewith, but have, with or without default upon their part, or for any other cause, not received title therefor, if such applicants or grantees and their heirs have occupied and cultivated said lands continuously since the filing of their applications.\n\"(b) Those who by themselves or through their predecessors-in-interest have been, in continuous, exclusive, and notorious possession and occupation of agricultural lands of the public domain, under a bona fide claim of acquisition or ownership, for at least thirty years immediately preceding the filing of the application for confirmation of title, except when prevented by war of force majeure. Those shall be conclusively presumed to have performed all the conditions essential to a government grant and shall be entitled to a certificate of title under the provisions of this chapter.\n\"(c) Members of the national cultural minorities who by themselves or through their predecessors-in-interest have been in open, continuous, exclusive and notorious possession and occupation of lands of the public domain suitable to agriculture, whether disposable or not, under a bona fide claim of ownership for at least 30 years shall be entitled to the rights granted in sub-section (b) hereof\"."}},{"id":"PH-H3175-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 120 of the same Act is hereby amended to read as follows:\n\"Sec. 120. Conveyance and encumbrance made by persons belonging to the so-called \"non-christian Filipinos\" or national cultural minorities, when proper, shall be valid if the person making the conveyance or encumbrance is able to read and can understand the language in which the instrument of conveyance or encumbrances is written. Conveyances or encumbrances made by illiterate non-Christian or literate non-Christians where the instrument of conveyance or encumbrance is in a language not understood by the said literate non-Christians shall not be valid unless duly approved by the Chairman of the Commission on National Integration.\""}},{"id":"PH-H3175-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Any Act, law, rule and regulation or executive order contrary hereto are hereby amended and/or repealed accordingly."}},{"id":"PH-H3175-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1964"}}],"pack":"ph-p45","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Public Land Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3176"] = {"id":"PH-H3176","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3873_1964.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将公共图书馆局更名为国家图书馆的法案","en":"An Act Changing the Name of the Bureau of Public Libraries to the National Library","orig":"An Act Changing the Name of the Bureau of Public Libraries to the National Library"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3873","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3873_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3176-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Bureau of Public Libraries is hereby changed to that of The National Library."}},{"id":"PH-H3176-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All references to the Bureau of Public Libraries in laws, executive orders, rules and regulations shall henceforth be understood to refer to The National Library."}},{"id":"PH-H3176-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1964."}}],"pack":"ph-p45","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Bureau of Public Libraries to the National Library","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3177"] = {"id":"PH-H3177","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3874_1964.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"为布拉干省增设助理省检察官，为此修订《行政法典》（经修正）第1674条的法案","en":"An Act to Provide Additional Assistant Provincial Fiscals for the Province of Bulacan, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","orig":"An Act to Provide Additional Assistant Provincial Fiscals for the Province of Bulacan, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 3874","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3874_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3177-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provision of Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Bulacan, is further amended to read as follows:\n\"Bulacan, eight assistant provincial fiscals;\""}},{"id":"PH-H3177-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The five incumbent special counsels in the Province of Bulacan shall automatically fill the positions of the five additional assistant fiscals provided for in this Act in accordance with their seniority, without need of any new appointments."}},{"id":"PH-H3177-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1964."}}],"pack":"ph-p45","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide Additional Assistant Provincial Fiscals for the Province of Bulacan, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3178"] = {"id":"PH-H3178","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3875_1964.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Naval市","en":"An Act Converting Naval Emergency Hospital in the Municipality of Naval, Province of Leyte, into a General Hospital to be Known as Naval General Hospital, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Converting Naval Emergency Hospital in the Municipality of Naval, Province of Leyte, into a General Hospital to be Known as Naval General Hospital, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 3875","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3875_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3178-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Naval Emergency Hospital in the Municipality of Naval, Province of Leyte, is hereby converted into a general hospital to be known as Naval General Hospital."}},{"id":"PH-H3178-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, for the conversion, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-five. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3178-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1964."}}],"pack":"ph-p45"};
  FT["PH-H3179"] = {"id":"PH-H3179","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3876_1964.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"授予 Dipolog 制冰与冷藏公司在北三宝颜省 Dipolog 市镇维护和运营制冰厂与冷藏库并销售分销冰和供应冷藏的特许权法案","en":"An Act Granting the Dipolog Ice Plant and Cold Storage Company, a Franchise to Maintain and Operate an Ice Plant and Cold Storage in the Municipality of Dipolog, Province of Zamboanga del Norte, and to Sell and Distribute Ice and Supply Cold Storage Therein","orig":"An Act Granting the Dipolog Ice Plant and Cold Storage Company, a Franchise to Maintain and Operate an Ice Plant and Cold Storage in the Municipality of Dipolog, Province of Zamboanga del Norte, and to Sell and Distribute Ice and Supply Cold Storage Therein"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 3876","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-18","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3876_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3179-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in this Act and in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to the Dipolog Ice Plant and Cold Storage Company, hereinafter called the grantee, for a period of twenty-five years from the approval of this Act, the right, the privilege and authority to construct, maintain and operate an ice plant and cold storage in the Municipality of Dipolog, Province of Zamboanga del Norte, and to sell and distribute ice and supply cold storage therein, and to charge and collect a schedule of prices and rates for the ice and cold storage so furnished which schedule of prices and rates shall at all times be subject to regulation by the Public Service Commission."}},{"id":"PH-H3179-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall manufacture ice up to the limit of the capacity of its plant, said limit to be determined by the Public Service Commission."}},{"id":"PH-H3179-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect, and the grantee shall, whenever the Public Service Commission shall determine that public interest reasonably requires it, change or alter any of its apparatus and appurtenances at grantees’s expense."}},{"id":"PH-H3179-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"If the grantee shall not commence the manufacture and distribution of ice and the supply of cold storage within one year from the approval of this Act, unless prevented by an act of God or force majeure, martial law, riot, commotion, usurpation by a military power or any other cause beyond the grantee’s control, this franchise shall become null and void."}},{"id":"PH-H3179-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise is granted subject to the provisions of the Constitution and Commonwealth Act Numbered One hundred forty-six, as amended, and with the understanding and upon the condition that it shall be subject to amendment, alteration or repeal by the Congress of the Philippines when public interest so requires."}},{"id":"PH-H3179-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"In the event of any competing individual, association of persons, or corporation, receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons, or corporation."}},{"id":"PH-H3179-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1964."}}],"pack":"ph-p45","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Dipolog Ice Plant and Cold Storage Company, a Franchise to Maintain and Operate an Ice Plant and Cold Storage in the Municipality of Dipolog, Province of Zamboanga del Norte, and to Sell and Distribute Ice and Supply Cold Storage Therein","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3180"] = {"id":"PH-H3180","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3877_1964.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"规定将东米萨米斯省 Alubijid 省立中学改设为国立综合中学并授权为此拨款的法案","en":"An Act to Provide for the Conversion of Alubijid Provincial High School in the Province of Misamis Oriental into a National Comprehensive High School and to Authorize the Appropriation of Funds Therefor","orig":"An Act to Provide for the Conversion of Alubijid Provincial High School in the Province of Misamis Oriental into a National Comprehensive High School and to Authorize the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3877","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-18","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3877_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3180-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Alubijid Provincial High School in the Municipality of Alubijid, Province of Misamis Oriental, is hereby converted into a national comprehensive high school to be known as Alubijid National Comprehensive High School under the direct supervision of the Director of Public Schools."}},{"id":"PH-H3180-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Alubijid National Comprehensive High School shall offer general secondary, vocational, adult education and folk school courses in accordance with the curriculum that may be prescribed by the Bureau of Public Schools: Provided, That adult education and folk school courses shall be given during the late afternoon or early evening classes."}},{"id":"PH-H3180-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Immediately upon the conversion of the Alubijid Provincial High School into the Alubijid National Comprehensive High School, all assets and liabilities of the former shall be transferred, borne, shouldered, owned, and assumed by the latter: Provided, That all teachers and/or employees now employed in the Alubijid Provincial High School shall be retained upon the conversion of the said school into the Alubijid National Comprehensive High School in accordance with or subject to the Civil Service Law or regulations applicable: Provided, further, That immediately upon conversion all teachers and/or employees employed therein shall receive their salaries in accordance with the rates corresponding to their qualifications as provided for by the WAPCO."}},{"id":"PH-H3180-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Director of Public Schools is hereby authorized to reorganize the said school in accordance with the purposes of this Act and the laws, rules, and executive orders applicable."}},{"id":"PH-H3180-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The sum of two hundred fifty thousand pesos is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, for the conversion, operation, and maintenance of the said school during the fiscal year that this Act shall be approved: Provided, That, thereafter, such sums as may be needed for the operation and maintenance of this school shall be appropriated and included in the annual General Appropriations Act."}},{"id":"PH-H3180-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1964."}}],"pack":"ph-p45","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide for the Conversion of Alubijid Provincial High School in the Province of Misamis Oriental into a National Comprehensive High School and to Authorize the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3181"] = {"id":"PH-H3181","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3878_1964.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定在北拉瑙省Kolambugan市镇设立急诊医院，名称为Kolambugan急诊医院，并授权为此拨款的法案","en":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Kolambugan, Province of Lanao del Norte, to be Known as Kolambugan Emergency Hospital, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Kolambugan, Province of Lanao del Norte, to be Known as Kolambugan Emergency Hospital, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 3878","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3878_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3181-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the direct supervision of the Director of Medical Services, an emergency hospital in the Municipality of Kolambugan, Province of Lanao del Norte, to be known as Kolambugan Emergency Hospital."}},{"id":"PH-H3181-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-five. Thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3181-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1964."}}],"pack":"ph-p45","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Kolambugan, Province of Lanao del Norte, to be Known as Kolambugan Emergency Hospital, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
