  FT["PH-H3199"] = {"id":"PH-H3199","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1964/ra_3896_1964.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Libon市","en":"An Act Declaring Certain Barrios in the Municipality of Libon, Province of Albay, as Duly Constituted Barrios Thereof","orig":"An Act Declaring Certain Barrios in the Municipality of Libon, Province of Albay, as Duly Constituted Barrios Thereof"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3896","issuingBody":"Congress of the Philippines","promulgatedDate":"1964-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1964/ra_3896_1964.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3199-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Sagrada Familia, Villa Petrona, Talintalin, Tambo, Rawis, Bariw, Alongong, Marique, San Ramon, Sta. Cruz and Sto. Niño in the Municipality of Libon, Province of Albay, are hereby declared as duly constituted barrios of said municipality, to be known as the barrios of Sagrada Familia, Villa Petrona, Talintalin, Tambo, Rawis, Bariw, Alongong, Marique, San Ramon, Sta. Cruz and Sto. Niño, respectively."}},{"id":"PH-H3199-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1964."}}],"pack":"ph-p45"};
